import pyomo.environ as pyo

DATA = {
    "buildings": ["X", "Y"],
    "cost": {"X": 50, "Y": 70},
    "requirement_contribution": {"X": 5, "Y": 10},
    "min_total_requirement": 100,
    "max_total_buildings": 20,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.BUILDINGS = pyo.Set(initialize=d["buildings"])

    model.build = pyo.Var(
        model.BUILDINGS,
        within=pyo.NonNegativeIntegers,
    )

    def obj_rule(m):
        return sum(d["cost"][b] * m.build[b] for b in m.BUILDINGS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def min_requirement_rule(m):
        return sum(
            d["requirement_contribution"][b] * m.build[b] for b in m.BUILDINGS
        ) >= d["min_total_requirement"]

    model.min_requirement = pyo.Constraint(rule=min_requirement_rule)

    def max_total_rule(m):
        return sum(m.build[b] for b in m.BUILDINGS) <= d["max_total_buildings"]

    model.max_total = pyo.Constraint(rule=max_total_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "building_types": ["X", "Y"],
    "cost": {"X": 50, "Y": 70},
    "contribution": {"X": 5, "Y": 10},
    "min_total_units": 100,
    "max_buildings": 20,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.T = pyo.Set(initialize=d["building_types"])

    def domain_bounds_rule(m, t):
        return (0, d["max_buildings"])

    model.x = pyo.Var(
        model.T,
        domain=pyo.NonNegativeIntegers,
        bounds=domain_bounds_rule,
    )

    def objective_rule(m):
        return sum(d["cost"][t] * m.x[t] for t in m.T)

    model.obj = pyo.Objective(expr=objective_rule, sense=pyo.minimize)

    def min_units_rule(m):
        return sum(d["contribution"][t] * m.x[t] for t in m.T) >= d["min_total_units"]

    model.min_units = pyo.Constraint(rule=min_units_rule)

    def max_buildings_rule(m):
        return sum(m.x[t] for t in m.T) <= d["max_buildings"]

    model.max_buildings = pyo.Constraint(rule=max_buildings_rule)

    return model
